contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint deposited = amount;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balanceAfterFirstWithdraw = address(c).balance;
        uint balanceAfterZeroCreditWithdraw = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balanceAfterSecondWithdraw = address(c).balance;

        assert(deposited == amount && balanceAfterZeroCreditWithdraw == balanceAfterFirstWithdraw && balanceAfterSecondWithdraw == balanceAfterFirstWithdraw);
    }

    receive() external payable {}
}

